SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END rating_bucket, city, CASE WHEN country IN ('TH', 'JP') THEN 'core' ELSE 'other' END country_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) city_values, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) berlin_count FROM suppliers WHERE rating < 3.4 AND country = 'UK' AND country IN ('UK', 'JP') GROUP BY 1, 2, 3 ORDER BY 3 DESC, rating_bucket, city LIMIT 3;
